<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;class TenantMembership extends Model{protected $fillable=['public_id','tenant_id','user_id','role_code','status','assigned_by','approved_at'];protected function casts():array{return['approved_at'=>'datetime'];}public function tenant():BelongsTo{return $this->belongsTo(Tenant::class);}public function user():BelongsTo{return $this->belongsTo(User::class);}}
